            preferredRecordBoardPageIndex = recordBoardPageIndex;
            GreedLastLobbySnapshot snapshot = markProfileSeen ? backend.MarkProfileSeen() : backend.LoadLobby();
            stateMachine.SetInfiniteRecordBoard(
