            }

            if (prompt.Contains("[급박]", StringComparison.Ordinal))
            {
                return "급박: 빠른 준비";
            }

            if (prompt.Contains("[정밀]", StringComparison.Ordinal))
            {
                return "정밀: 정박 노림";
            }

            if (prompt.Contains("[연쇄]", StringComparison.Ordinal))
