            pauseMenuBodyText = CreateText(panel.transform, "PauseMenuBody", string.Empty, 29, TextAnchor.MiddleCenter, FontStyle.Normal);
            SetAnchored(pauseMenuBodyText.rectTransform, 0.5f, 0.61f, 650f, 160f);
